import React, { Component } from 'react';
import { Card, Button, Spin, Alert, Select, Form, Input, Radio, message, Icon } from 'antd';
import { getInstance } from 'd2/lib/d2';
import PropTypes from 'prop-types';

const { Option } = Select;
const { TextArea } = Input;

class CreateProgram extends Component {
    constructor(props) {
        super(props);
        this.state = {
            thematicAreas: [],
            loading: false,
            saving: false,
            error: null,
            selectedThematicArea: null,
            programName: '',
            programCode: '',
            programDescription: '',
            programType: 'WITHOUT_REGISTRATION'
        };
        this._isMounted = false;
    }

    componentDidMount() {
        this._isMounted = true;
        this.fetchThematicAreas();
    }

    componentWillUnmount() {
        this._isMounted = false;
    }

    fetchThematicAreas = async () => {
        if (!this._isMounted) return;

        this.setState({ loading: true, error: null });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();
            const data = await api.get('organisationUnits', {
                level: 2,
                paging: false,
                fields: 'id,displayName,code'
            });

            if (this._isMounted) {
                this.setState({
                    thematicAreas: data.organisationUnits || [],
                    loading: false
                });
            }
        } catch (error) {
            console.error('Error fetching thematic areas:', error);
            if (this._isMounted) {
                this.setState({
                    error: 'Failed to fetch thematic areas. Please try again.',
                    loading: false
                });
            }
        }
    };

    handleThematicAreaChange = (value) => {
        this.setState({ selectedThematicArea: value });
    };

    handleInputChange = (field, value) => {
        this.setState({ [field]: value });
    };

    handleCancel = () => {
        window.history.back();
    };

    handleSubmit = async () => {
        const { selectedThematicArea, programName, programCode, programType, programDescription } = this.state;

        if (!selectedThematicArea) {
            message.error('Please select a thematic area');
            return;
        }

        if (!programName.trim()) {
            message.error('Please enter a program name');
            return;
        }

        this.setState({ saving: true });

        try {
            const d2 = await getInstance();
            const api = d2.Api.getApi();

            // Create the program (level 3 organization unit) nested under the selected thematic area
            const orgUnitPayload = {
                name: programName,
                displayName: programName,
                shortName: programName.substring(0, 50), // DHIS2 shortName limit
                code: programCode || undefined,
                openingDate: new Date().toISOString().split('T')[0],
                level: 3,
                parent: {
                    id: selectedThematicArea
                }
            };

            const orgUnitResponse = await api.post('organisationUnits', orgUnitPayload);
            const newOrgUnitId = orgUnitResponse.response.uid;

            // Create the program associated with this organization unit
            const programPayload = {
                name: programName,
                displayName: programName,
                shortName: programName.substring(0, 50),
                code: programCode || undefined,
                description: programDescription || undefined,
                programType: programType,
                organisationUnits: [
                    {
                        id: newOrgUnitId
                    }
                ],
                userRoles: [],
            };

            const programResponse = await api.post('programs', programPayload);
            const newProgramId = programResponse.response.uid;

            message.success('Program created successfully!');

            // Redirect to edit the newly created program
            const redirectUrl = `/sims-web-maintenance/#/edit/programSection/program/${newProgramId}`;
            window.location.href = redirectUrl;

        } catch (error) {
            console.error('Error creating program:', error);
            this.setState({ saving: false });

            let errorMessage = 'Failed to create program. Please try again.';
            if (error.response && error.response.data && error.response.data.message) {
                errorMessage = error.response.data.message;
            }

            message.error(errorMessage);
        }
    };

    render() {
        const {
            thematicAreas,
            loading,
            saving,
            error,
            selectedThematicArea,
            programName,
            programCode,
            programDescription,
            programType
        } = this.state;

        const cardStyle = {
            margin: '20px auto',
            maxWidth: '800px',
            borderRadius: '8px',
            boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
        };

        const headerStyle = {
            padding: '24px',
            borderRadius: '8px 8px 0 0',
            borderBottom: '1px solid #f0f0f0'
        };

        if (loading) {
            return (
                <Card style={cardStyle}>
                    <div style={{ textAlign: 'center', padding: '60px 0' }}>
                        <Spin size="large" />
                        <div style={{ marginTop: '16px', fontSize: '16px', color: '#666' }}>
                            Loading thematic areas...
                        </div>
                    </div>
                </Card>
            );
        }

        if (error) {
            return (
                <Card style={cardStyle}>
                    <div style={{ padding: '40px' }}>
                        <Alert
                            message="Error Loading Data"
                            description={error}
                            type="error"
                            showIcon
                            action={
                                <Button size="small" type="primary" onClick={this.fetchThematicAreas}>
                                    Try Again
                                </Button>
                            }
                        />
                    </div>
                </Card>
            );
        }

        return (
            <div>
                <Card bodyStyle={{ padding: 0 }}>
                    {/* Header */}
                    <div style={headerStyle}>
                        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                            <div>
                                <h1 style={{
                                    margin: 0,
                                    fontSize: '24px',
                                    fontWeight: 'bold',
                                }}>
                                    Create New Program
                                </h1>
                                <p style={{ margin: '8px 0 0 0', color: '#666' }}>
                                    Create a new program and automatically add it under a selected thematic area
                                </p>
                            </div>
                            <Button
                                icon="arrow-left"
                                onClick={this.handleCancel}
                                size="large"
                            >
                                Back
                            </Button>
                        </div>
                    </div>

                    {/* Form Content */}
                    <div style={{ padding: '32px' }}>
                        <Form layout="vertical">
                            <Form.Item
                                label="Select Thematic Area"
                                required
                                help="Choose which thematic area this program will be nested under"
                            >
                                <Select
                                    placeholder="Select a thematic area"
                                    value={selectedThematicArea}
                                    onChange={this.handleThematicAreaChange}
                                    size="large"
                                    showSearch
                                    filterOption={(input, option) =>
                                        option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
                                    }
                                >
                                    {thematicAreas.map(area => (
                                        <Option key={area.id} value={area.id}>
                                            <Icon type="folder" style={{ marginRight: '8px', color: '#1890ff' }} />
                                            {area.displayName}
                                        </Option>
                                    ))}
                                </Select>
                            </Form.Item>

                            <Form.Item
                                label="Program Name"
                                required
                            >
                                <Input
                                    placeholder="Enter program name"
                                    value={programName}
                                    onChange={(e) => this.handleInputChange('programName', e.target.value)}
                                    size="large"
                                />
                            </Form.Item>

                            <Form.Item
                                label="Program Code"
                                help="Optional unique identifier for the program"
                            >
                                <Input
                                    placeholder="Enter program code (optional)"
                                    value={programCode}
                                    onChange={(e) => this.handleInputChange('programCode', e.target.value)}
                                    size="large"
                                />
                            </Form.Item>

                            <Form.Item
                                label="Program Type"
                                required
                            >
                                <Radio.Group
                                    value={programType}
                                    onChange={(e) => this.handleInputChange('programType', e.target.value)}
                                    size="large"
                                >
                                    <Radio.Button value="WITHOUT_REGISTRATION">
                                        <Icon type="file-text" style={{ marginRight: '8px' }} />
                                        Forms Data Project
                                    </Radio.Button>
                                    <Radio.Button value="WITH_REGISTRATION">
                                        <Icon type="table" style={{ marginRight: '8px' }} />
                                        Spreadsheet Data Project
                                    </Radio.Button>
                                </Radio.Group>
                            </Form.Item>

                            <Form.Item
                                label="Description"
                                help="Optional description for the program"
                            >
                                <TextArea
                                    placeholder="Enter program description (optional)"
                                    value={programDescription}
                                    onChange={(e) => this.handleInputChange('programDescription', e.target.value)}
                                    rows={4}
                                />
                            </Form.Item>

                            <Form.Item style={{ marginTop: '32px' }}>
                                <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end' }}>
                                    <Button
                                        size="large"
                                        onClick={this.handleCancel}
                                        disabled={saving}
                                    >
                                        Cancel
                                    </Button>
                                    <Button
                                        type="primary"
                                        size="large"
                                        onClick={this.handleSubmit}
                                        loading={saving}
                                        disabled={!selectedThematicArea || !programName.trim()}
                                    >
                                        <Icon type="plus" />
                                        Create Program
                                    </Button>
                                </div>
                            </Form.Item>
                        </Form>
                    </div>
                </Card>
            </div>
        );
    }
}

CreateProgram.contextTypes = {
    d2: PropTypes.object
};

export default CreateProgram;



